import React, { useEffect, useState } from "react";

export default function AlertToast({ alerts }) {
  const [visible, setVisible] = useState(false);
  const [current, setCurrent] = useState(null);
  const prevCount = React.useRef(0);

  useEffect(() => {
    const bottles = alerts.filter(a => a.type !== "camera_alert");
    if (bottles.length > prevCount.current && bottles.length > 0) {
      setCurrent(bottles[0]);
      setVisible(true);
      const t = setTimeout(() => setVisible(false), 4000);
      prevCount.current = bottles.length;
      return () => clearTimeout(t);
    }
    prevCount.current = bottles.length;
  }, [alerts]);

  if (!visible || !current) return null;

  return (
    <div style={{
      position: "fixed", top: 72, right: 24, zIndex: 1000,
      background: "#1a1d27", border: "1px solid #ef4444",
      borderLeft: "4px solid #ef4444",
      borderRadius: 10, padding: "14px 18px", minWidth: 280,
      boxShadow: "0 8px 32px rgba(0,0,0,0.5)",
      animation: "slideIn .25s ease",
    }}>
      <style>{`@keyframes slideIn { from { transform: translateX(120%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }`}</style>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
        <div>
          <div style={{ fontSize: 12, fontWeight: 700, color: "#ef4444", letterSpacing: 0.5, marginBottom: 4 }}>
            ALCOHOL BOTTLE DETECTED
          </div>
          <div style={{ fontSize: 13, color: "#d1d5db" }}>
            {current.class} — {(current.confidence * 100).toFixed(0)}% confidence
          </div>
          <div style={{ fontSize: 11, color: "#6b7280", marginTop: 4 }}>
            {new Date(current.timestamp).toLocaleTimeString()}
          </div>
        </div>
        <button
          onClick={() => setVisible(false)}
          style={{ background: "none", border: "none", color: "#6b7280",
                   cursor: "pointer", fontSize: 16, padding: 0, lineHeight: 1 }}>
          ×
        </button>
      </div>
      {/* Progress bar auto-dismiss */}
      <div style={{ marginTop: 10, height: 2, background: "#2a2d3a", borderRadius: 1 }}>
        <div style={{
          height: "100%", background: "#ef4444", borderRadius: 1,
          animation: "shrink 4s linear forwards",
        }} />
      </div>
      <style>{`@keyframes shrink { from { width: 100%; } to { width: 0%; } }`}</style>
    </div>
  );
}
